CREATE OR REPLACE FUNCTION public.admin_save_question(_id bigint,_stem text,_options jsonb,_answer text,_explanation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE html text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF length(btrim(_stem)) NOT BETWEEN 1 AND 100000 OR length(_explanation)>200000 OR jsonb_typeof(_options)<>'array' OR jsonb_array_length(_options)<2 OR jsonb_array_length(_options)>5 OR _answer NOT IN ('A','B','C','D','E') OR ascii(_answer)-64>jsonb_array_length(_options) THEN RAISE EXCEPTION 'Check question content and the answer letter'; END IF; html:=concat(_stem,_explanation,_options::text); IF html ~* '<\s*(script|iframe|object|embed|svg|math|form|style|link|meta|base)' OR html ~* '\son[a-z]+\s*=' OR html ~* '(javascript|vbscript|data)\s*:' THEN RAISE EXCEPTION 'Executable HTML is not allowed'; END IF; UPDATE public.questions SET stem=_stem,options=_options,answer=_answer,explanation=_explanation WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Question not found'; END IF; INSERT INTO public.admin_audit(actor_id,action,entity,record_key,changed_fields) VALUES(auth.uid(),'update','questions',_id::text,'["stem","options","answer","explanation"]'); END $$;
CREATE OR REPLACE FUNCTION public.console_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; fields jsonb; BEGIN IF TG_OP='UPDATE' THEN NEW.updated_at=now(); END IF; IF TG_TABLE_NAME='feature_settings' THEN NEW.updated_by=auth.uid(); END IF; IF TG_TABLE_NAME='subscriptions' THEN IF NEW.amount_paid_paise<0 OR length(NEW.allocation_note)>500 THEN RAISE EXCEPTION 'Invalid allocation amount or note'; END IF; END IF; IF TG_OP='INSERT' THEN SELECT jsonb_agg(key) INTO fields FROM jsonb_each(to_jsonb(NEW)); ELSE SELECT jsonb_agg(n.key) INTO fields FROM jsonb_each(to_jsonb(NEW)) n WHERE n.value IS DISTINCT FROM to_jsonb(OLD)->n.key AND n.key NOT IN ('updated_at','updated_by'); END IF; k:=coalesce(to_jsonb(NEW)->>'id',to_jsonb(NEW)->>'key',to_jsonb(NEW)->>'code',''); IF fields IS NOT NULL AND public.has_role(auth.uid(),'admin') THEN INSERT INTO public.admin_audit(actor_id,action,entity,record_key,changed_fields) VALUES(auth.uid(),lower(TG_OP),TG_TABLE_NAME,k,fields); END IF; RETURN NEW; END $$;
DO $$ DECLARE admin_id uuid; student_id uuid; test_sid uuid:=gen_random_uuid(); allocation_id uuid; denied boolean; BEGIN SELECT user_id INTO admin_id FROM public.user_roles WHERE role='admin' LIMIT 1; SELECT id INTO student_id FROM public.profiles p WHERE NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=p.id AND r.role='admin') LIMIT 1; IF admin_id IS NULL OR student_id IS NULL THEN RAISE EXCEPTION 'Need existing administrator and student for rule checks'; END IF;
BEGIN
 PERFORM set_config('request.jwt.claims','{}',true); denied:=false; BEGIN PERFORM public.admin_all_plans(); EXCEPTION WHEN OTHERS THEN IF SQLERRM='Administrator access required' THEN denied:=true; ELSE RAISE; END IF; END; IF NOT denied THEN RAISE EXCEPTION 'Signed-out administrator read was allowed'; END IF;
 INSERT INTO public.account_devices(user_id,session_id,device_id,device_name) VALUES(student_id,test_sid,gen_random_uuid(),'Rollback rule test'); PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',student_id,'session_id',test_sid,'role','authenticated')::text,true);
 denied:=false; BEGIN PERFORM public.admin_allocate_access(student_id,'panacea',6,current_date,0,'test'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='Administrator access required' THEN denied:=true; ELSE RAISE; END IF; END; IF NOT denied THEN RAISE EXCEPTION 'Student self-allocation was allowed'; END IF;
 PERFORM public.track_purchase_stage('coupon_page','panacea',12,'web'); IF NOT EXISTS(SELECT 1 FROM public.purchase_journey WHERE user_id=student_id AND stage='coupon_page' AND created_at>now()-interval '1 minute') THEN RAISE EXCEPTION 'Owner purchase tracking failed'; END IF;
 test_sid:=gen_random_uuid(); INSERT INTO public.account_devices(user_id,session_id,device_id,device_name) VALUES(admin_id,test_sid,gen_random_uuid(),'Rollback admin test'); PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'session_id',test_sid,'role','authenticated')::text,true);
 allocation_id:=public.admin_allocate_access(student_id,'panacea',6,'2026-11-20',0,'Free test'); IF NOT EXISTS(SELECT 1 FROM public.subscriptions WHERE id=allocation_id AND amount_paid_paise=0 AND starts_at='2026-11-20'::timestamptz AND ends_at='2027-05-20'::timestamptz) THEN RAISE EXCEPTION 'Free six-month allocation failed'; END IF;
 allocation_id:=public.admin_allocate_access(student_id,'panacea',6,'2026-11-20',75000,'Custom price test'); IF NOT EXISTS(SELECT 1 FROM public.subscriptions WHERE id=allocation_id AND amount_paid_paise=75000) THEN RAISE EXCEPTION 'Custom paid allocation failed'; END IF;
 UPDATE public.feature_settings SET enabled=false WHERE key='checkout'; test_sid:=gen_random_uuid(); INSERT INTO public.account_devices(user_id,session_id,device_id,device_name) VALUES(student_id,test_sid,gen_random_uuid(),'Rollback checkout test'); PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',student_id,'session_id',test_sid,'role','authenticated')::text,true);
 denied:=false; BEGIN PERFORM public.quote_plan('panacea',12,'NIRMAYACARE'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='Plan purchases are currently disabled' THEN denied:=true; ELSE RAISE; END IF; END; IF NOT denied THEN RAISE EXCEPTION 'Disabled checkout was usable'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.admin_audit WHERE entity='subscriptions' AND record_key=allocation_id::text) THEN RAISE EXCEPTION 'Allocation audit missing'; END IF;
 RAISE EXCEPTION 'ROLLBACK_RULE_TESTS_PASSED';
EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'ROLLBACK_RULE_TESTS_PASSED' THEN RAISE; END IF; END;
END $$;